// History + send (spec/server-chat/00-brief.md §5.2/§5.3/§5.9/§5.7) — this
// parcel's own `server/api/<area>.ts`, calling through P4's `serverFetch` so
// the token/401 handling stays in one place (`http.ts`'s own docstring).

import { ServerErasureOutcomeUnknownError, ServerLockedError, serverFetch } from "./http";
import type { DrawingSummary } from "./drawings";
import type { WyrSummary } from "./wyr";
import type { AdventureSummary } from "../adventure/api";
import type { CookoutSummary } from "../cookout/api";
import type { ServerSession } from "../types";

import type { AttachmentTranscript } from "../mediaRender";

export type AttachmentKind = "photo" | "video" | "voice";
export type AttachmentStatus = "processing" | "ready" | "failed";
export type { AttachmentTranscript };

export interface Attachment {
  readonly id: string;
  readonly kind: AttachmentKind;
  readonly status: AttachmentStatus;
  readonly width: number | null;
  readonly height: number | null;
  readonly durationS: number | null;
  readonly peaks: readonly number[] | null;
  readonly urls: {
    readonly full?: string;
    readonly thumb?: string;
    readonly poster?: string;
    readonly play?: string;
  };
  /** Absent on a server that predates transcripts; `null` until someone asks for one. */
  readonly transcript?: AttachmentTranscript | null;
  /** True for a ready animated GIF: the bubble shows the moving `full` rendition, not the
   * still `thumb`. Absent on a server that predates the flag. */
  readonly animated?: boolean;
}

/** One emoji on one message: who reacted, oldest first (spec/server-chat/04-reactions.md). */
export interface Reaction {
  readonly emoji: string;
  readonly count: number;
  readonly senders: readonly string[];
}

/** Round 2 ruling item 10 §(3): the `media` member of a quote — `null` for a
 * text-only target. `kind` is the quoted attachments' shared kind, or
 * `"mixed"`; `durationS` is the single voice note's or video's duration only
 * when `count === 1`; `thumbUrl` is a freshly signed URL for the FIRST
 * attachment's `thumb` (photo) or `poster` (video) rendition, only when that
 * attachment is `ready` — never `full`/`play`, and never present for voice. */
export interface ReplyToMedia {
  readonly kind: AttachmentKind | "mixed";
  readonly count: number;
  readonly durationS: number | null;
  readonly thumbUrl: string | null;
  readonly viewOnce?: boolean;
}

/** Round 2 ruling item 10 §(3): the `replyTo` member of the `Message` wire
 * shape — `null` for an ordinary message. Built fresh by the server from the
 * LIVE target row on every read (Inv 40/Inv 46): deleting the target makes
 * this `null` everywhere it was quoted, with no chat-visible tombstone. */
export interface ReplyTo {
  readonly seq: number;
  readonly sender: string;
  readonly text: string | null;
  readonly truncated: boolean;
  readonly media: ReplyToMedia | null;
}

export interface ViewOnceInfo {
  readonly durationS: 2 | 5 | 30 | null;
  readonly tease: boolean;
}

export interface Message {
  readonly seq: number;
  readonly clientId: string;
  readonly sender: string;
  readonly text: string | null;
  readonly attachments: readonly Attachment[];
  readonly reactions: readonly Reaction[];
  readonly createdAt: number;
  readonly replyTo: ReplyTo | null;
  readonly viewOnce?: ViewOnceInfo | null;
  /** A blank drawing surface (the header's ... menu): no text, no attachments. Absent from a
   * server that predates canvases — read as "not a canvas". */
  readonly canvas?: boolean;
  /** spec/server-chat/07-live-drawing.md §4: a summary of the drawings anchored to this message
   * (never their strokes). Absent from a server that predates drawings — read as "unknown",
   * never as "none" (`parseDrawingSummaries`). */
  readonly drawings?: readonly DrawingSummary[];
  /** The would-you-rather round anchored to this message (summary only — never the answers).
   * Absent or null on a server that predates the game, or on an ordinary message. */
  readonly wyr?: WyrSummary | null;
  /** The would-you-rather round (its anchor message's seq) this message was sent in the game
   * chat of — null/absent for an ordinary message or on a server that predates the game chat. */
  readonly wyrRef?: number | null;
  /** Which game `wyrRef` belongs to (resolved by the server at read time, so a client paging history
   * need not have the anchor loaded): "wyr", "adventure" or "cookout"; null with `wyrRef`. Absent from
   * a server that predates Adventure Time (read as unknown: the anchor itself, if loaded, says). Read it
   * through `parseWyrRefKind`, which turns anything else into "unknown". */
  readonly wyrRefKind?: WyrRefKind | null;
  /** The Adventure Time round anchored to this message (summary only: never the spin, landing or
   * pack). Absent or null on a server that predates the game, or on an ordinary message. */
  readonly adventure?: AdventureSummary | null;
  /** The Cookout round anchored to this message (spec/server-chat/09-cookout.md §4.2): states and counts
   * only — never an ingredient, an option or a recipe. Absent or null on a server that predates the game,
   * or on an ordinary message. Read it through `parseCookoutSummary` (cookout/api.ts): the wire is not
   * trusted to have this shape. */
  readonly cookout?: CookoutSummary | null;
}

/** The games a game-chat message (`wyrRef`) can belong to. */
export type WyrRefKind = "wyr" | "adventure" | "cookout";

/** `wyrRefKind` as one of the known games, or null when absent or not one this client knows (the
 * caller then asks the anchor message itself). */
export function parseWyrRefKind(value: unknown): WyrRefKind | null {
  return value === "wyr" || value === "adventure" || value === "cookout" ? value : null;
}

export interface HistoryPage {
  readonly messages: readonly Message[];
  readonly hasMore: boolean;
  readonly cursor: number;
}

/** §5.2: `before` omitted fetches the newest page; the client walks OLDER
 * pages by passing the oldest loaded message's `seq` back in as `before`. */
export async function getHistory(
  session: ServerSession,
  opts: { before?: number; limit?: number } = {},
): Promise<HistoryPage> {
  const params = new URLSearchParams();
  if (opts.before !== undefined) params.set("before", String(opts.before));
  params.set("limit", String(opts.limit ?? 50));
  const response = await serverFetch(`/messages?${params.toString()}`, { method: "GET" }, session);
  if (!response.ok) throw new Error(`Couldn't load history (${response.status}).`);
  return (await response.json()) as HistoryPage;
}

export interface SendMessageInput {
  readonly clientId: string;
  readonly sender: string;
  readonly deviceId: string;
  readonly text: string | null;
  readonly attachmentIds: readonly string[];
  /** Round 2 ruling item 10 §(3): omit the key entirely for an ordinary
   * message — never send it as `undefined` explicitly. */
  readonly replyToSeq?: number;
  /** Send into a game item's chat — a would-you-rather round's OR an Adventure Time round's anchor
   * seq (the historical name means "the game-chat anchor of ANY game"); omit for the main chat. */
  readonly wyrSeq?: number;
}

export type SendMessageResult =
  | { readonly ok: true; readonly message: Message }
  | { readonly ok: false; readonly kind: "invalid"; readonly detail: string }
  /** Any other 4xx except the transient 408/429: the server has judged this exact
   * payload and will judge it the same way again, so a retry cannot succeed. */
  | { readonly ok: false; readonly kind: "rejected"; readonly status: number }
  /** Any transport failure, or a status this client doesn't have a specific
   * mapping for — the composer surfaces a generic "couldn't send" error and
   * keeps the draft (retry reuses the same `clientId`, §5.3's idempotency). */
  | { readonly ok: false; readonly kind: "unavailable" };

/** A verdict on the SEND: a 4xx other than the transient 408 (timeout) and 429 (rate limit)
 * — and other than 403, which wixy's own send route never answers, so it can only come
 * from Cloudflare Access or a WAF in front of it (an expired session, a false positive)
 * and says nothing about the recording. (A 401 never gets here: `serverFetch` turns it into
 * a lock.) */
export function isDefinitiveSendRejectionStatus(status: number): boolean {
  return status >= 400 && status < 500 && status !== 403 && status !== 408 && status !== 429;
}

export async function sendMessage(
  session: ServerSession,
  input: SendMessageInput,
): Promise<SendMessageResult> {
  let response: Response;
  try {
    response = await serverFetch(
      "/messages",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      },
      session,
    );
  } catch (error) {
    // A 401 must keep propagating as a lock trigger (R6) — only a genuine
    // transport failure (network down, timeout) becomes "unavailable".
    if (error instanceof ServerLockedError) throw error;
    return { ok: false, kind: "unavailable" };
  }
  if (response.status === 201 || response.status === 200) {
    const body = (await response.json()) as { message: Message };
    return { ok: true, message: body.message };
  }
  if (response.status === 422) {
    const body = (await response.json().catch(() => null)) as { detail?: string } | null;
    return { ok: false, kind: "invalid", detail: body?.detail ?? "Couldn't send that message." };
  }
  if (isDefinitiveSendRejectionStatus(response.status)) {
    return { ok: false, kind: "rejected", status: response.status };
  }
  return { ok: false, kind: "unavailable" };
}

/** The server refused or could not apply a reaction (a 401 never gets here: `serverFetch`
 * turns it into a lock). `status` 404 means the message is gone. */
export class ReactionRequestError extends Error {
  readonly status: number;

  constructor(status: number) {
    super(`Couldn't update the reaction (${status}).`);
    this.name = "ReactionRequestError";
    this.status = status;
  }
}

export interface SetReactionInput {
  readonly emoji: string;
  readonly sender: string;
  /** The DESIRED state, not a toggle: a retry after a dropped response can't flip it back. */
  readonly reacted: boolean;
}

/** Sets one reactor's emoji on one message and returns the message as the server now
 * holds it. */
export async function setReaction(
  session: ServerSession,
  seq: number,
  input: SetReactionInput,
): Promise<Message> {
  const response = await serverFetch(
    `/messages/${encodeURIComponent(String(seq))}/reactions`,
    {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(input),
    },
    session,
  );
  if (!response.ok) throw new ReactionRequestError(response.status);
  const body = (await response.json()) as { message: Message };
  return body.message;
}

const DELETE_UNKNOWN_RETRY_MS = [1_000, 2_000, 4_000] as const;

function waitForDeleteRetry(delayMs: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, delayMs));
}

export async function deleteMessage(session: ServerSession, seq: number): Promise<boolean> {
  const path = `/messages/${encodeURIComponent(String(seq))}`;
  for (let attempt = 0; ; attempt += 1) {
    try {
      const response = await serverFetch(path, { method: "DELETE" }, session);
      if (!response.ok) throw new Error(`Couldn't delete message (${response.status}).`);
      if (response.status === 202) {
        const body = (await response.json()) as { erasurePending: boolean };
        return body.erasurePending;
      }
      return false;
    } catch (error) {
      if (error instanceof ServerLockedError) throw error;
      if (!(error instanceof ServerErasureOutcomeUnknownError) || attempt >= DELETE_UNKNOWN_RETRY_MS.length) {
        throw error;
      }
      await waitForDeleteRetry(DELETE_UNKNOWN_RETRY_MS[attempt] ?? 4_000);
    }
  }
}

/** After a request was sent, a 408 or any 5xx says nothing about whether the server acted
 * on it: wixy's own commit may have landed, and Cloudflare (502/504/524...) sits in front
 * and answers for the origin. Only a 4xx says the request was refused. */
function isUnknownOutcomeStatus(status: number): boolean {
  return status === 408 || status >= 500;
}

export async function wipeChat(session: ServerSession): Promise<boolean> {
  const response = await serverFetch(
    "/wipe",
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ confirm: "WIPE" }),
    },
    session,
  );
  // A wipe is not idempotent: reporting a committed wipe as a definite failure would invite
  // a second one that deletes everything sent since. Treat it like a dropped connection and
  // let the thread reconcile against history (never re-POSTing).
  if (isUnknownOutcomeStatus(response.status)) throw new ServerErasureOutcomeUnknownError();
  if (!response.ok) throw new Error(`Couldn't delete messages (${response.status}).`);
  if (response.status === 202) {
    const body = (await response.json()) as { erasurePending: boolean };
    return body.erasurePending;
  }
  return false;
}

export interface UsageInfo {
  readonly usedBytes: number;
  readonly quotaBytes: number;
  readonly freeBytes: number;
  readonly mediaAvailable: boolean;
  readonly erasurePending: boolean;
  /** cmd's private transcription mode is live, so the Transcribe control may be offered. */
  readonly transcriptionAvailable?: boolean;
}

export async function getUsage(session: ServerSession, signal?: AbortSignal): Promise<UsageInfo> {
  const response = await serverFetch("/usage", { method: "GET", ...(signal ? { signal } : {}) }, session);
  if (!response.ok) throw new Error(`Couldn't load storage usage (${response.status}).`);
  return (await response.json()) as UsageInfo;
}

/** What asking the server to transcribe a voice note came back with. */
export type TranscribeAnswer =
  /** 202: a job is running (or was already); `transcript` is `pending`. */
  | { readonly kind: "started"; readonly transcript: AttachmentTranscript }
  /** 200: a stored transcript, served straight back. */
  | { readonly kind: "done"; readonly transcript: AttachmentTranscript }
  /** 503: cmd cannot promise private mode (or this is the standalone edition). */
  | { readonly kind: "unavailable" }
  /** 429: too many new transcripts this minute. */
  | { readonly kind: "rate_limited"; readonly retryAfterS: number }
  /** 404: the note no longer exists (deleted, or never a sent voice note). */
  | { readonly kind: "gone" }
  /** 409: the note is still being processed. */
  | { readonly kind: "not_ready" }
  /** Anything else, including a dropped connection: nothing is known to have started. */
  | { readonly kind: "failed" };

function parseTranscript(value: unknown): AttachmentTranscript | null {
  if (typeof value !== "object" || value === null) return null;
  const record = value as { status?: unknown; text?: unknown };
  if (record.status === "pending" || record.status === "failed") {
    const text = typeof record.text === "string" ? record.text : undefined;
    return text !== undefined ? { status: record.status, text } : { status: record.status };
  }
  if (record.status === "done" && typeof record.text === "string") {
    return { status: "done", text: record.text };
  }
  return null;
}

/** `POST /attachments/{id}/transcribe` — asynchronous: the server answers at once (202) and the
 * finished transcript arrives as a `message_updated` stream event. A 401 propagates as a lock. */
export async function transcribeAttachment(
  session: ServerSession,
  attachmentId: string,
  options?: { retranscribe?: boolean },
): Promise<TranscribeAnswer> {
  let response: Response;
  const query = options?.retranscribe ? "?retranscribe=1" : "";
  try {
    response = await serverFetch(
      `/attachments/${encodeURIComponent(attachmentId)}/transcribe${query}`,
      { method: "POST" },
      session,
    );
  } catch (error) {
    if (error instanceof ServerLockedError) throw error;
    return { kind: "failed" };
  }
  if (response.status === 200 || response.status === 202) {
    const body = (await response.json().catch(() => null)) as { transcript?: unknown } | null;
    const transcript = parseTranscript(body?.transcript);
    if (transcript === null) return { kind: "failed" };
    return { kind: response.status === 200 ? "done" : "started", transcript };
  }
  if (response.status === 503) return { kind: "unavailable" };
  if (response.status === 404) return { kind: "gone" };
  if (response.status === 409) return { kind: "not_ready" };
  if (response.status === 429) {
    const body = (await response.json().catch(() => null)) as { retryAfterS?: unknown } | null;
    const retryAfterS = typeof body?.retryAfterS === "number" ? body.retryAfterS : 60;
    return { kind: "rate_limited", retryAfterS };
  }
  return { kind: "failed" };
}

export interface SendViewOnceInput {
  readonly clientId: string;
  readonly sender: string;
  readonly deviceId: string;
  readonly attachmentId: string;
  readonly durationS: 2 | 5 | 30 | null;
  readonly tease: boolean;
  readonly replyToSeq?: number;
}

export type SendViewOnceResult =
  | { readonly ok: true; readonly message: Message }
  | { readonly ok: false; readonly kind: "not_ready" }
  | { readonly ok: false; readonly kind: "unsupported" }
  | { readonly ok: false; readonly kind: "invalid"; readonly detail: string }
  | { readonly ok: false; readonly kind: "rejected"; readonly status: number }
  | { readonly ok: false; readonly kind: "unavailable" };

export async function sendViewOnceMessage(
  session: ServerSession,
  input: SendViewOnceInput,
): Promise<SendViewOnceResult> {
  let response: Response;
  try {
    response = await serverFetch(
      "/messages/view-once",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      },
      session,
    );
  } catch (error) {
    if (error instanceof ServerLockedError) throw error;
    return { ok: false, kind: "unavailable" };
  }
  if (response.status === 201 || response.status === 200) {
    const body = (await response.json()) as { message: Message };
    return { ok: true, message: body.message };
  }
  if (response.status === 404 || response.status === 405) {
    return { ok: false, kind: "unsupported" };
  }
  if (response.status === 422) {
    const body = (await response.json().catch(() => null)) as { error?: string; detail?: string } | null;
    if (body?.error === "not_ready") {
      return { ok: false, kind: "not_ready" };
    }
    return { ok: false, kind: "invalid", detail: body?.detail ?? "Couldn't send that message." };
  }
  if (isDefinitiveSendRejectionStatus(response.status)) {
    return { ok: false, kind: "rejected", status: response.status };
  }
  return { ok: false, kind: "unavailable" };
}

export type SendCanvasResult =
  | { readonly ok: true; readonly message: Message }
  | { readonly ok: false; readonly kind: "unsupported" | "rejected" | "unavailable" };

/** Adds a blank canvas to the thread. Idempotent on `clientId`, like every send. */
export async function sendCanvasMessage(
  session: ServerSession,
  input: { readonly clientId: string; readonly sender: string; readonly deviceId: string },
): Promise<SendCanvasResult> {
  let response: Response;
  try {
    response = await serverFetch(
      "/messages/canvas",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      },
      session,
    );
  } catch (error) {
    if (error instanceof ServerLockedError) throw error;
    return { ok: false, kind: "unavailable" };
  }
  if (response.status === 201 || response.status === 200) {
    const body = (await response.json()) as { message: Message };
    return { ok: true, message: body.message };
  }
  // A server that predates canvases has no such route (404/405).
  if (response.status === 404 || response.status === 405) return { ok: false, kind: "unsupported" };
  if (isDefinitiveSendRejectionStatus(response.status)) return { ok: false, kind: "rejected" };
  return { ok: false, kind: "unavailable" };
}

export interface OpenViewOnceSuccess {
  readonly durationS: 2 | 5 | 30 | null;
  readonly tease: boolean;
  readonly kind: "photo" | "video";
  readonly mime: string;
}

export type OpenViewOnceResult =
  | { readonly ok: true; readonly data: OpenViewOnceSuccess }
  | { readonly ok: false; readonly kind: "not_found" }
  | { readonly ok: false; readonly kind: "own_message" }
  | { readonly ok: false; readonly kind: "already_opened" }
  | { readonly ok: false; readonly kind: "unavailable" };

export async function openViewOnceClaim(
  session: ServerSession,
  seq: number,
  input: { claimId: string; sender: string },
): Promise<OpenViewOnceResult> {
  let response: Response;
  try {
    response = await serverFetch(
      `/messages/${encodeURIComponent(String(seq))}/view-once/open`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      },
      session,
    );
  } catch (error) {
    if (error instanceof ServerLockedError) throw error;
    return { ok: false, kind: "unavailable" };
  }
  if (response.status === 200) {
    const data = (await response.json()) as OpenViewOnceSuccess;
    return { ok: true, data };
  }
  if (response.status === 404) return { ok: false, kind: "not_found" };
  if (response.status === 403) return { ok: false, kind: "own_message" };
  if (response.status === 409) return { ok: false, kind: "already_opened" };
  return { ok: false, kind: "unavailable" };
}

export type FetchViewOnceContentResult =
  | { readonly ok: true; readonly blob: Blob }
  | { readonly ok: false; readonly kind: "not_found" }
  | { readonly ok: false; readonly kind: "forbidden" }
  | { readonly ok: false; readonly kind: "expired" }
  | { readonly ok: false; readonly kind: "unavailable" };

export async function fetchViewOnceContent(
  session: ServerSession,
  seq: number,
  claimId: string,
  signal?: AbortSignal,
): Promise<FetchViewOnceContentResult> {
  let response: Response;
  try {
    response = await serverFetch(
      `/messages/${encodeURIComponent(String(seq))}/view-once/content`,
      {
        method: "GET",
        headers: { "X-Wixy-View-Claim": claimId },
        ...(signal !== undefined ? { signal } : {}),
      },
      session,
      120_000,
    );
    if (response.status === 200) {
      const blob = await response.blob();
      return { ok: true, blob };
    }
  } catch (error) {
    if (error instanceof ServerLockedError) throw error;
    return { ok: false, kind: "unavailable" };
  }
  if (response.status === 404) return { ok: false, kind: "not_found" };
  if (response.status === 403) return { ok: false, kind: "forbidden" };
  if (response.status === 410) return { ok: false, kind: "expired" };
  return { ok: false, kind: "unavailable" };
}
